var budget = new ArcSlider
{
    Label = "Monthly budget",
    Min = 0,
    Max = 100,
    Step = 5,
    Value = 40,
    Marks = new[] { new ArcSliderMark(0), new ArcSliderMark(50), new ArcSliderMark(100) },
    Format = value => $"${value:0}",
    Description = "方向键每次 5，PageUp 跳 10。"
};

budget.ValueChanged += (_, _) => Preview(budget.Value);
budget.ValueCommitted += (_, _) => Save(budget.Value);
